function preparar(datos) {
  const { nombre, ...extras } = datos;
  return { nombre: nombre ?? 'Anónimo', ...extras, nombre };
}

function prepararVista(datos) {
  const { id, nombre, perfil, ...extras } = datos;
  return {
    id,
    nombre: nombre || 'Anónimo',
    ciudad: perfil.direccion.ciudad || 'Sin ciudad',
    tema: perfil.preferencias.tema || 'claro',
    extras,
  };
}
